"""Local hsm state: when each host was last used.

Lives in ~/.config/hsm/state.toml, separate from hosts.toml: that file is
meant to be version-controlled, and updating a timestamp on every connect
would fill the git history with worthless changes.

    # Generated by hsm: do not edit by hand.
    [last_used]
    web01 = 2026-10-16T10:00:00Z

It's convenience data, but it reveals which machines you use and when: that's
why it is 0600 too. If two hsm processes write at the same time the last one
wins; for sorting `hsm ls` that's acceptable.
"""

import tomllib
from collections.abc import Callable, Iterable
from datetime import UTC, datetime
from pathlib import Path

import tomlkit

from hsm.errors import HsmError
from hsm.fsutil import atomic_write, ensure_private_dir, read_private
from hsm.inventory import is_valid_alias

_HEADER = "Generated by hsm: do not edit by hand."


class StateError(HsmError):
    """Invalid state.toml."""


class State:
    """Last-use timestamp per alias, always in UTC and to the second."""

    def __init__(self, path: Path, last_used: dict[str, datetime]) -> None:
        self._path = path
        self._last_used = last_used

    @classmethod
    def load(cls, path: Path) -> "State":
        """Read `path`; if it doesn't exist, empty state."""
        try:
            raw = read_private(path)
        except FileNotFoundError:
            return cls(path, {})
        except PermissionError as exc:
            # E.g. mode 0000: not a security problem, just unreadable.
            raise StateError(f"{path}: cannot read ({exc.strerror})") from None
        # tomllib is enough here (read-only, standard library): we always
        # write the whole file, there is nothing of the user's to preserve.
        try:
            data = tomllib.loads(raw.decode("utf-8"))
        except (tomllib.TOMLDecodeError, UnicodeDecodeError) as exc:
            raise StateError(f"{path}: invalid TOML ({exc})") from None
        except RecursionError:
            # tomllib is recursive: thousands of nested lists exhaust the stack.
            raise StateError(f"{path}: TOML nested too deeply") from None
        section = data.get("last_used", {})
        if not isinstance(section, dict):
            raise StateError(f"{path}: 'last_used' must be a table")
        last_used: dict[str, datetime] = {}
        for alias, value in section.items():
            if not is_valid_alias(alias):
                raise StateError(f"{path}: invalid alias {alias!r}")
            # datetime is a subclass of date: a date without a time doesn't
            # pass, and neither does a time without a timezone.
            if not isinstance(value, datetime) or value.tzinfo is None:
                raise StateError(f"{path}: {alias} must be a date and time with a timezone")
            try:
                last_used[alias] = _normalize(value)
            except OverflowError:
                raise StateError(f"{path}: {alias} has an out-of-range date") from None
        return cls(path, last_used)

    @classmethod
    def load_or_empty(cls, path: Path, warn: Callable[[str], None]) -> "State":
        """Like `load`, but a broken file becomes an empty state with a warning.

        The state can be regenerated: it must never prevent a connect. Overly
        broad permissions, however, remain an error, as for the other hsm
        files (InsecurePermissionsError is not a StateError).
        """
        try:
            return cls.load(path)
        except StateError as exc:
            warn(f"{exc}. Ignoring the saved state; it will be rewritten.")
            return cls(path, {})

    def last_used(self, alias: str) -> datetime | None:
        return self._last_used.get(alias)

    def touch(self, alias: str, when: datetime | None = None) -> None:
        """Record a use of `alias` (default: now)."""
        if not is_valid_alias(alias):
            raise ValueError(f"invalid alias: {alias!r}")
        when = datetime.now(UTC) if when is None else when
        if when.tzinfo is None:
            raise ValueError("a timezone-aware datetime is required")
        try:
            self._last_used[alias] = _normalize(when)
        except OverflowError:
            raise ValueError(f"date out of range: {when!r}") from None

    def forget(self, alias: str) -> None:
        self._last_used.pop(alias, None)

    def rename(self, old: str, new: str) -> None:
        """Move the last use of `old` to the new alias (if there was one)."""
        if not is_valid_alias(new):
            raise ValueError(f"invalid alias: {new!r}")
        if old in self._last_used:
            self._last_used[new] = self._last_used.pop(old)

    def prune(self, known: Iterable[str]) -> None:
        """Forget aliases that are no longer in the inventory."""
        keep = set(known)
        for alias in [a for a in self._last_used if a not in keep]:
            del self._last_used[alias]

    def recent(self, aliases: Iterable[str]) -> list[str]:
        """Sort `aliases`: most recently used first, never used at the end."""

        def key(alias: str) -> tuple[bool, float, str]:
            used = self._last_used.get(alias)
            # (never used?, -timestamp, alias): never-used ones go last,
            # ties are sorted by name.
            return (used is None, -used.timestamp() if used else 0.0, alias)

        return sorted(aliases, key=key)

    def save(self, *, dry_run: bool = False) -> str:
        """Rewrite the whole file (0600, atomic) and return its text."""
        doc = tomlkit.document()
        doc.add(tomlkit.comment(_HEADER))
        table = tomlkit.table()
        for alias in sorted(self._last_used):
            table[alias] = self._last_used[alias]
        doc["last_used"] = table
        text = tomlkit.dumps(doc)
        if not dry_run:
            ensure_private_dir(self._path.parent)
            atomic_write(self._path, text.encode("utf-8"))
        return text


def _normalize(when: datetime) -> datetime:
    """UTC, to the second: more precision isn't needed and would make the file noisy.

    May raise OverflowError if the conversion to UTC falls outside years
    1..9999 (e.g. 0001-01-01T00:00:00+05:00).
    """
    return when.astimezone(UTC).replace(microsecond=0)
